const StateTooltip = ({ state, x, y, containerRef }) => {
  const [position, setPosition] = useState({ top: y, left: x });

  useEffect(() => {

    if (!containerRef.current) return;
    const containerRect = containerRef.current.getBoundingClientRect();
    const tooltipWidth = 220;
    const tooltipHeight = 120;
    let newX = x - containerRect.left + 10;
    let newY = y - containerRect.top + 10;

    if (newX + tooltipWidth > containerRect.width) {
      newX = x - containerRect.left - tooltipWidth - 20;
    }
    if (newY + tooltipHeight > containerRect.height) {
      newY = y - containerRect.top - tooltipHeight - 20;
    }

    setPosition({ top: newY, left: newX });
  }, [x, y, containerRef]);

  return (

  <div className="absolute z-20 bg-white/95 backdrop-blur-sm border border-gray-200 rounded-xl shadow-2xl min-w-[150px] max-w-[150px] max-h-[260px] overflow-y-auto sm:min-w-[200px] sm:max-h-none sm:p-4" style={{ top: position.top, left: position.left }}>
     <h3 className="text-base font-bold text-gray-800 sm:text-lg">
    {state.name}
  </h3>
  <div className="flex flex-col gap-2 mt-2 sm:gap-3">
    {state.famous.map((item, index) => (
      <div key={index} className="flex items-center gap-2 sm:gap-3">
        <img
          src={state.images[index] || FALLBACK_IMAGE}
          alt={item}
          loading="lazy"
          className="w-10 h-10 sm:w-14 sm:h-14 rounded-full object-cover border-2 border-gray-100 shadow-sm transform hover:scale-105 transition-transform duration-300"
          onError={(e) => (e.target.src = FALLBACK_IMAGE)}
        />
        <span className="text-xs text-gray-600 font-medium sm:text-sm">
          {item}
        </span>
      </div>
    ))}
  </div>
</div>


  );
};


const MapPath = ({
  id,
  d,
  isHovered,
  onHover,
  onLeave,
  isMapVisible,
  isConnected,
}) => {
  
  const pathExists = paths.some((path) => path.id === id);
  if (!pathExists) return null;

  const state = stateData[id];
  const isWestBengal = id === "wb";

  const offsets = {

    ar: { x: -25, y: -15 }, 
    as: { x: 15, y: -5 }, 
    mn: { x: 10, y: 5 }, 
    ml: { x: -5, y: 15 }, 
    mz: { x: -10, y: 10 }, 
    nl: { x: 5, y: -15 },
    tr: { x: -15, y: 5 }, 
    sk: { x: -25, y: 0 }, 
    wb: { x: -20, y: 5 },
  };

  const imageOffsets = {

    ar: { x: 254, y: 0, width: "60%", height: "38%" }, 
    as: { x: 130, y: 68, width: "67%", height: "62%" }, 
    mn: { x: 350, y: 300, width: "25%", height: "25%" }, 
    ml: { x: 80, y: 260, width: "45%", height: "26%" }, 
    mz: { x: 315, y: 405, width: "14%", height: "32%" }, 
    nl: { x: 378, y: 198, width: "20%", height: "24%" }, 
    tr: { x: 240, y: 413, width: "15%", height: "24%" }, 
    sk: { x: -20, y: 120, width: "18%", height: "24%" }
  };

  return (
    <g
      className={`transition-all duration-1000 ease-in-out ${
        isMapVisible ? "opacity-100" : "opacity-0"
      } ${isConnected ? "" : "translate"}`}
      style={{
        transform: isConnected
          ? "translate(0, 0)"
          : `translate(${offsets[id]?.x || 0}px, ${offsets[id]?.y || 0}px)`,
      }}
    >
      <clipPath id={`clip-${id}`}>
        <path d={d} />
      </clipPath>
      {!isWestBengal && state && (
        <image 
          href={
            isHovered
              ? state.images[0] || FALLBACK_IMAGE
              : state.defaultImage || FALLBACK_IMAGE
          }
          x={imageOffsets[id]?.x || 0}
          y={imageOffsets[id]?.y || 0}
          width={imageOffsets[id]?.width || "100%"}
          height={imageOffsets[id]?.height || "100%"}
          preserveAspectRatio="xMidYMid slice"
          clipPath={`url(#clip-${id})`}
          className="transition-opacity duration-500"
          onError={(e) => (e.target.src = FALLBACK_IMAGE)}
        />
      )}
      <path
        id={id}
        d={d}
        fill={isWestBengal ? "#ffffffff" : "transparent"} 
        stroke="#1d1f1dff"
        strokeWidth="1"
        className={`transition-all duration-300 ease-in-out ${
          !isWestBengal ? "cursor-pointer hover:opacity-80" : ""
        }`}
        onMouseEnter={
          !isWestBengal && state ? (e) => onHover(id, e) : undefined
        }
        onMouseLeave={!isWestBengal && state ? onLeave : undefined}
      />
    </g>
  );
};


export default function NortheastIndiaMap() {
  const [hovered, setHovered] = useState(null);
  const [coords, setCoords] = useState({ x: 0, y: 0 });
  const [isMapVisible, setIsMapVisible] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const containerRef = React.useRef(null);

  useEffect(() => {
    const mapTimer = setTimeout(() => {
      setIsMapVisible(true);
      const connectTimer = setTimeout(() => {
        setIsConnected(true);
      }, 2000);
      return () => clearTimeout(connectTimer);
    }, 3000);

    return () => clearTimeout(mapTimer);
  }, []);

  const handleMouseEnter = (id, e) => {
    if (id !== "wb" && paths.some((path) => path.id === id) && stateData[id]) {
      setHovered(id);
      setCoords({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e) => {
    if (hovered) {
      setCoords({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseLeave = () => {
    setHovered(null);
  };

  return (
    <div
      ref={containerRef}

      className="relative w-full h-auto min-h-[400px] max-h-[1000px] mx-auto shadow-lg overflow-hidden sm:h-[50vh] md:h-[90vh]" >
      <div
        className="absolute inset-0 bg-cover bg-center slideshow"
        style={{ opacity: 0.8 }}
      />
      <svg
        viewBox="0 0 642.59 600"
        preserveAspectRatio="xMidYMid meet"
        className={`w-full h-full relative z-10 transition-opacity duration-1000 ease-in-out ${
          isMapVisible ? "opacity-100" : "opacity-0"
        }`}
        onMouseMove={handleMouseMove}
      >
        {paths.map(({ id, d }) => (
          <MapPath 
            key={id}
            id={id}
            d={d}
            isHovered={hovered === id}
            onHover={handleMouseEnter}
            onLeave={handleMouseLeave}
            isMapVisible={isMapVisible}
            isConnected={isConnected}
          />
        ))}
      </svg>

      {hovered && stateData[hovered] && (
        <StateTooltip
          state={stateData[hovered]}
          x={coords.x}
          y={coords.y}
          containerRef={containerRef}
        />
      )}

      <style jsx>{`
        @keyframes slide-in {
          from {
            opacity: 0;
            transform: translateY(-10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        @keyframes slideshow {
          0% {
            background-image: url("${backgroundImages[0]}");
          }
          25% {
            background-image: url("${backgroundImages[1]}");
          }
          50% {
            background-image: url("${backgroundImages[2]}");
          }
          75% {
            background-image: url("${backgroundImages[3]}");
          }
            100% {
            background-image: url("${backgroundImages[4]}");
          }
        }
        .animate-slide-in {
          animation: slide-in 0.6s ease-out;
        }
        .translate {
          opacity: 0.2;
          filter: drop-shadow(0 0 10px rgba(0, 0, 0, 0.3));
        }
        .slideshow {
          animation: slideshow 15s infinite;
        }
      `}</style>
    </div>
  );
}
